namespace Atom;

/// <summary>
///     Provides functionality to generate C# code for .NET CLI commands based on a parsed schema.
/// </summary>
/// <remarks>
///     This static class is used by the <see cref="Build" /> definition in <c>Invex.Atom.DotnetCliGenerator</c>
///     to create strongly-typed interfaces, implementations, and option classes for `dotnet` commands.
/// </remarks>
public static class DotnetCliGenerator
{
    /// <summary>
    ///     The first line of every generated file. Used to recognise generated files when deleting stale ones.
    /// </summary>
    public const string AutoGeneratedHeader = "// <auto-generated/>";

    /// <summary>
    ///     Flattens the command tree under <paramref name="rootCommand" /> and returns the commands to generate.
    /// </summary>
    /// <param name="rootCommand">The parsed root <c>dotnet</c> command.</param>
    /// <returns>The flattened, filtered commands, in schema order.</returns>
    /// <remarks>
    ///     Hidden commands and options are removed (see <see cref="DotnetCliParser.FlattenCommands" />), as are
    ///     <c>help</c>, <c>completions script</c> and option-style legacy commands (names starting with <c>-</c>).
    /// </remarks>
    /// <exception cref="InvalidOperationException">Thrown if two commands would produce the same C# name.</exception>
    public static IReadOnlyList<Command> GetCommandsToGenerate(Command rootCommand)
    {
        var flattenedCommands = new List<Command>();

        foreach (var subCommand in rootCommand.SubCommands)
            DotnetCliParser.FlattenCommands(string.Empty, subCommand, flattenedCommands);

        var commands = flattenedCommands
            .Where(static x => x.Name.ToLowerInvariant() is not "completions script" and not "help" &&
                               !x.Name.Split(' ').Any(static part => part.StartsWith('-')))
            .ToList();

        var duplicate = commands
            .GroupBy(static x => CsharpWriter.ToPascalCase(x.Name), StringComparer.OrdinalIgnoreCase)
            .FirstOrDefault(static g => g.Count() > 1);

        return duplicate is not null
            ? throw new InvalidOperationException(
                $"Commands {string.Join(", ", duplicate.Select(static x => $"'{x.Name}'"))} would all generate '{duplicate.Key}'.")
            : commands;
    }

    /// <summary>
    ///     Generates the complete C# source file for a single command.
    /// </summary>
    /// <param name="command">The flattened command.</param>
    /// <returns>The file contents.</returns>
    public static string GenerateFile(Command command)
    {
        var writer = new CsharpWriter();

        writer.WriteLine(AutoGeneratedHeader);
        writer.WriteLine(string.Empty);
        writer.WriteLine("#nullable enable");
        writer.WriteLine(string.Empty);
        writer.WriteLine("namespace Invex.Atom.Module.Dotnet.Cli;");
        writer.WriteLine(string.Empty);

        GenerateInterfaceCode(writer, command);
        GenerateImplementationCode(writer, command);
        GenerateOptionsCode(writer, command);

        return writer.ToString();
    }

    /// <summary>
    ///     Generates the C# interface code for a given .NET CLI command.
    /// </summary>
    /// <param name="writer">The <see cref="CsharpWriter" /> to write the code to.</param>
    /// <param name="command">The <see cref="Command" /> object representing the .NET CLI command.</param>
    /// <remarks>
    ///     This method generates a method signature within the `IDotnetCli` interface for the command,
    ///     including overloads for single arguments and path-like arguments where applicable.
    /// </remarks>
    public static void GenerateInterfaceCode(CsharpWriter writer, Command command)
    {
        using (writer.Block("public partial interface IDotnetCli"))
        {
            GenerateCommandMethod(writer, command, true);

            if (command.Arguments.Count is 0)
                return;

            var singleArg = command.Arguments[0];

            // Generate overload for single argument
            if (singleArg.ValueType.EndsWith("[]", StringComparison.Ordinal))
                GenerateCommandMethod(writer,
                    command with
                    {
                        Arguments =
                        [
                            command.Arguments[0] with
                            {
                                ValueType = singleArg.ValueType.Replace("[]", string.Empty),
                            },
                        ],
                    },
                    true);

            // Generate overload for a single argument that is a path
            if (singleArg.ValueType is "System.String" or "System.String[]" &&
                (singleArg.Name.Contains("path", StringComparison.OrdinalIgnoreCase) ||
                 (singleArg.Description ?? "").Contains("path", StringComparison.OrdinalIgnoreCase) ||
                 singleArg.Name.Contains("file", StringComparison.OrdinalIgnoreCase) ||
                 (singleArg.Description ?? "").Contains("file", StringComparison.OrdinalIgnoreCase)))
                GenerateCommandMethod(writer,
                    command with
                    {
                        Arguments =
                        [
                            command.Arguments[0] with
                            {
                                ValueType = "Invex.FileSystem.RootedPath",
                            },
                        ],
                    },
                    true);
        }

        writer.WriteLine(string.Empty);
    }

    /// <summary>
    ///     Generates the C# implementation code for a given .NET CLI command.
    /// </summary>
    /// <param name="writer">The <see cref="CsharpWriter" /> to write the code to.</param>
    /// <param name="command">The <see cref="Command" /> object representing the .NET CLI command.</param>
    /// <remarks>
    ///     This method generates the actual implementation of the command within the `DotnetCli` class,
    ///     including overloads for single arguments and path-like arguments where applicable.
    ///     It constructs the command-line arguments and invokes the `dotnet` process.
    /// </remarks>
    public static void GenerateImplementationCode(CsharpWriter writer, Command command)
    {
        using (writer.Block("internal partial class DotnetCli"))
        {
            GenerateCommandMethod(writer, command, false);

            if (command.Arguments.Count is 0)
                return;

            var singleArg = command.Arguments[0];

            // Generate overload for single argument
            if (singleArg.ValueType.EndsWith("[]", StringComparison.Ordinal))
                GenerateCommandMethod(writer,
                    command with
                    {
                        Arguments =
                        [
                            command.Arguments[0] with
                            {
                                ValueType = singleArg.ValueType.Replace("[]", string.Empty),
                            },
                        ],
                    },
                    false);

            // Generate overload for a single argument that is a path
            if (singleArg.ValueType is "System.String" or "System.String[]" &&
                (singleArg.Name.Contains("path", StringComparison.OrdinalIgnoreCase) ||
                 (singleArg.Description ?? "").Contains("path", StringComparison.OrdinalIgnoreCase) ||
                 singleArg.Name.Contains("file", StringComparison.OrdinalIgnoreCase) ||
                 (singleArg.Description ?? "").Contains("file", StringComparison.OrdinalIgnoreCase)))
                GenerateCommandMethod(writer,
                    command with
                    {
                        Arguments =
                        [
                            command.Arguments[0] with
                            {
                                ValueType = "Invex.FileSystem.RootedPath",
                            },
                        ],
                    },
                    false);
        }

        writer.WriteLine(string.Empty);
    }

    /// <summary>
    ///     Gets the name of the generated options record for a command.
    /// </summary>
    /// <param name="command">The flattened command.</param>
    /// <returns>
    ///     The command name in PascalCase, prefixed with <c>Dotnet</c> and suffixed with <c>Options</c>
    ///     (e.g. <c>DotnetBuildOptions</c>), so it does not collide with other types such as
    ///     <c>Invex.Atom.Build.BuildOptions</c>.
    /// </returns>
    public static string GetOptionsTypeName(Command command) =>
        $"Dotnet{CsharpWriter.ToPascalCase(command.Name)}Options";

    /// <summary>
    ///     Generates the C# options record for a given .NET CLI command.
    /// </summary>
    /// <param name="writer">The <see cref="CsharpWriter" /> to write the code to.</param>
    /// <param name="command">The <see cref="Command" /> object representing the .NET CLI command.</param>
    /// <remarks>
    ///     This method creates a `sealed record` named after the command prefixed with `Dotnet` (e.g., `DotnetBuildOptions`)
    ///     that contains properties for each of the command's options. It also includes a `ToArguments()` method that
    ///     converts these options into a list of individual command-line arguments.
    /// </remarks>
    public static void GenerateOptionsCode(CsharpWriter writer, Command command)
    {
        if (command.Options.Count is 0)
            return;

        var options = command
            .Options
            .Where(static x => x.ValueType is not (null or "System.Void"))
            .ToList();

        writer.WriteLine("[PublicAPI]");

        using (writer.Block($"public sealed record {GetOptionsTypeName(command)}"))
        {
            foreach (var option in options)
                writer.WriteProperty("public",
                    GetOptionPropertyType(option),
                    CsharpWriter.ToPascalCase(option.Name),
                    new(null),
                    new(null, true),
                    null,
                    option.Description);

            writer.WriteLine("/// <summary>");
            writer.WriteLine("///     Converts these options to individual command-line arguments, in schema order.");
            writer.WriteLine("/// </summary>");
            writer.WriteLine("/// <returns>");
            writer.WriteLine("///     The arguments. Each option name and each value is a separate element, so values need no quoting.");
            writer.WriteLine("/// </returns>");

            writer.WriteMethod("public",
                "IReadOnlyList<string>",
                "ToArguments",
                Array.Empty<MethodParam>(),
                bodyWriter =>
                {
                    bodyWriter.WriteLine("var args = new List<string>();");

                    foreach (var option in options)
                        bodyWriter.WriteLine(
                            $"DotnetCliArgs.{GetOptionAddMethod(option)}(args, \"{option.Name}\", {CsharpWriter.ToPascalCase(option.Name)});");

                    bodyWriter.WriteLine(string.Empty);
                    bodyWriter.WriteLine("return args;");
                });
        }

        writer.WriteLine(string.Empty);
    }

    /// <summary>
    ///     Gets the C# property type used for an option in the generated options record.
    /// </summary>
    /// <param name="option">The option.</param>
    /// <returns>The nullable C# type name.</returns>
    private static string GetOptionPropertyType(Option option) =>
        IsKnownAotFriendlyType(option.ValueType)
            ? $"{FormatType(option.ValueType)}?"
            : "string?";

    /// <summary>
    ///     Gets the <c>DotnetCliArgs</c> method that adds an option to the argument list.
    /// </summary>
    /// <param name="option">The option.</param>
    /// <returns>
    ///     <c>AddFlag</c> for a boolean option that takes no value (emitted only when <c>true</c>), <c>AddBool</c> for a
    ///     boolean option that takes a value (emitted as <c>--name true|false</c> when not <c>null</c>), and
    ///     <c>AddOption</c> for everything else.
    /// </returns>
    private static string GetOptionAddMethod(Option option) =>
        FormatType(option.ValueType) is "System.Boolean"
            ? option.AcceptsValue
                ? "AddBool"
                : "AddFlag"
            : "AddOption";

    /// <summary>
    ///     Generates a C# method for a given .NET CLI command, either as an interface stub or an implementation.
    /// </summary>
    /// <param name="writer">The <see cref="CsharpWriter" /> to write the code to.</param>
    /// <param name="command">The <see cref="Command" /> object representing the .NET CLI command.</param>
    /// <param name="isStub">If <c>true</c>, generates an interface method signature; otherwise, generates an implementation.</param>
    private static void GenerateCommandMethod(CsharpWriter writer, Command command, bool isStub) =>
        writer.WriteMethod("public",
            "Task<ProcessRunResult>",
            CsharpWriter.ToPascalCase(command.Name),
            command
                .Arguments
                .Select(arg => new MethodParam(IsKnownAotFriendlyType(arg.ValueType)
                        ? FormatType(arg.ValueType)
                        : arg.ValueType is "Invex.FileSystem.RootedPath"
                            ? "Invex.FileSystem.RootedPath"
                            : "System.String",
                    CsharpWriter.ToPascalCase(arg.Name, true),
                    XmlDescription: arg.Description))
                .Append(command.Options.Count > 0
                    ? new MethodParam($"{GetOptionsTypeName(command)}?",
                        "options",
                        "null",
                        "Options")
                    : null)
                .Append(new("ProcessRunOptions?",
                    "processRunOptions",
                    "null",
                    "Process run options. NOTE: The name and arguments will be overridden by the appropriate dotnet command"))
                .Append(new("CancellationToken", "cancellationToken", "default", "Cancellation token"))
                .ToArray(),
            isStub
                ? null
                : bodyWriter =>
                {
                    var commandWords = command
                        .Name
                        .Split(' ', StringSplitOptions.RemoveEmptyEntries)
                        .Select(static word => $"\"{word}\"");

                    bodyWriter.WriteLine($"var args = new List<string> {{ {string.Join(", ", commandWords)} }};");

                    foreach (var arg in command.Arguments)
                        bodyWriter.WriteLine($"DotnetCliArgs.AddPositional(args, {CsharpWriter.ToPascalCase(arg.Name, true)});");

                    if (command.Options.Count > 0)
                        bodyWriter.WriteLine("args.AddRange((options ?? new()).ToArguments());");

                    bodyWriter.WriteLine(string.Empty);

                    bodyWriter.WriteLine(
                        "return processRunner.RunAsync(DotnetCliArgs.CreateRunOptions(args, processRunOptions), cancellationToken);");
                },
            false,
            isStub
                ? command.Description
                : null);

    /// <summary>
    ///     Formats a .NET type name for use in generated C# code, handling nullable types and specific replacements.
    /// </summary>
    /// <param name="type">The original type name from the CLI schema.</param>
    /// <returns>The formatted C# type name.</returns>
    private static string FormatType(string type)
    {
        // ReSharper disable once InvertIf
        if (type.StartsWith("System.Nullable<", StringComparison.Ordinal))
        {
            var closingBracketIndex = type.LastIndexOf('>');
            var innerType = type["System.Nullable<".Length..closingBracketIndex];
            type = innerType;
        }

        return type
            .Replace("System.Collections.ObjectModel.ReadOnlyDictionary",
                "System.Collections.Generic.IReadOnlyDictionary")
            .Replace("Microsoft.DotNet.Cli.PackageIdentityWithRange", "string")
            .Replace("Microsoft.DotNet.Cli.Utils.VerbosityOptions", "VerbosityOptions")
            .Replace("NuGet.CommandLine.XPlat.Commands.VerbosityEnum", "VerbosityOptions")
            .Replace("NuGet.CommandLine.XPlat.Commands.Package.Update.Package", "string");
    }

    /// <summary>
    ///     Determines if a given type name is considered "AOT-friendly" (i.e., can be used directly without causing
    ///     AOT/trimming issues).
    /// </summary>
    /// <param name="typeName">The name of the type to check.</param>
    /// <returns><c>true</c> if the type is considered AOT-friendly; otherwise, <c>false</c>.</returns>
    /// <remarks>
    ///     This method uses simple string checks to classify types. It explicitly allows
    ///     `Invex.FileSystem.RootedPath`, `Microsoft.DotNet.Cli.Utils.VerbosityOptions`,
    ///     and any type starting with "System." (assuming BCL types are generally AOT-friendly).
    /// </remarks>
    private static bool IsKnownAotFriendlyType(string? typeName)
    {
        if (string.IsNullOrWhiteSpace(typeName))
            return false;

        // Exclude void explicitly
        if (typeName is "void" or "System.Void")
            return false;

        // Handle single-dimensional arrays by checking the element type
        if (typeName.EndsWith("[]", StringComparison.Ordinal))
            typeName = typeName[..^2];

        if (typeName.StartsWith("System.Nullable`", StringComparison.Ordinal))
            typeName = typeName[(typeName.IndexOf('`') + 1)..];

        // Explicitly allow our known custom types and consider all BCL types under System.* as known
        return typeName is "Invex.FileSystem.RootedPath" or "Microsoft.DotNet.Cli.Utils.VerbosityOptions" ||
               typeName.StartsWith("System.", StringComparison.Ordinal);
    }
}
